<?php class RolModel {private PDO $pdo; function __construct(PDO $pdo){$this->pdo=$pdo;} function obtenerTodas(){return $this->pdo->query('SELECT r.*,COUNT(u.id_usuario) total_usuarios FROM roles r LEFT JOIN usuarios u ON u.id_rol=r.id_rol GROUP BY r.id_rol ORDER BY r.id_rol')->fetchAll();} function obtenerPorId($id){$s=$this->pdo->prepare('SELECT * FROM roles WHERE id_rol=?');$s->execute([$id]);return $s->fetch();} function crear($d){$s=$this->pdo->prepare('INSERT INTO roles(nombre_rol,descripcion) VALUES(?,?)');return $s->execute([$d['nombre_rol'],$d['descripcion']]);} function editar($id,$d){$s=$this->pdo->prepare('UPDATE roles SET nombre_rol=?,descripcion=? WHERE id_rol=?');return $s->execute([$d['nombre_rol'],$d['descripcion'],$id]);} function eliminar($id){$s=$this->pdo->prepare('DELETE FROM roles WHERE id_rol=?');return $s->execute([$id]);}}
